(function(){var d={"book": {"chapters": [{"container": "EXTENSION", "file": "vtm5e-0.5-book-of-nod-apocrypha-introduction.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Book of Nod: Apocrypha - Introduction", "page": 3, "roots": ["#vDr2UJgCDd2fg7pHCVVTHmR", "#vEi5BpujYMW41UIz1xlUJWO"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Book of Nod: Apocrypha - Chapter 1: Stories from the Land of Nod", "page": 6, "roots": ["#vdfqNXU1pYhu6fGUtzSV77f", "#vitDdkZYIFZc2irxtkOUShR", "#vEi8rlfjLZcyj5inOebULCG", "#vxt9FOsscR0jzHVxeS7AtbP", "#vb5xQtoAr5aIf6YLCdZAUOq", "#vgavXm3UCi00e2LIJBWnhGz", "#vMK72TyfmudeRW48CTrGxkI"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-book-of-nod-apocrypha-apocrypha.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Book of Nod: Apocrypha - Chapter 2: The Apocrypha", "page": 16, "roots": ["#vQOPa38pGNeeHpcuWgdGX2w", "#vKsiy3enw4ihqiYVR2EaRf8", "#vxPYMAPb4zfgvsqMAq0F1HL", "#v341wTHAvfAszDBRIVtbDAb", "#vooC179GUYmhk1NUoUeRMlq", "#v10MhQ8GfUuXPPew0bjTozn", "#vBUY0eULDUU09q64demfxCq"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-book-of-nod-apocrypha-kindred-laws-and-traditions.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Book of Nod: Apocrypha - Chapter 3: Kindred Laws and Traditions", "page": 25, "roots": ["#vrNMVQ3UXsWMPfVWKsvpWg8", "#vZqIozEUp9LCuiODs2i7mKv", "#vzbwSVjAYn0bRWkiC5Muj5C", "#vbkxEPN9lPbB30a4jsBPzYl", "#vMxdz90POu0D9YgMLjq4DH3", "#vuCni6P6OnrB94L5cyBSpl3", "#vJSRzEhs77zILaMt6Sy0pMN"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Book of Nod: Apocrypha - Chapter 4: Disciplines", "page": 32, "roots": ["#vYkBz5A9LbYLDyIh3gskbbl", "#vibhHqq9DeEvdzcLIZKNNz0", "#vZZ5K9156z6AGdtQum7cZ59", "#vaWaBS8y33ubwzb0KOpvMOc"]}, {"container": "EXTENSION", "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "kind": "ttrpg", "name": "Vampire: The Masquerade - The Book of Nod: Apocrypha - Loresheets", "page": 36, "roots": ["#vlb7c7YDmUeclLLOdamWvvq", "#vIOxJ8gUbNioVFL94kTKkME", "#vZdjJ9QO32JA1Ppu8rU8VUY", "#vkDXxgPBT2Ssuchhugys6Dl", "#vtFAEQT7PdM516PZcMZFvnG"]}], "entities": ["#vDr2UJgCDd2fg7pHCVVTHmR", "#vEi5BpujYMW41UIz1xlUJWO", "#vdfqNXU1pYhu6fGUtzSV77f", "#vitDdkZYIFZc2irxtkOUShR", "#vEi8rlfjLZcyj5inOebULCG", "#vxt9FOsscR0jzHVxeS7AtbP", "#vb5xQtoAr5aIf6YLCdZAUOq", "#vgavXm3UCi00e2LIJBWnhGz", "#vMK72TyfmudeRW48CTrGxkI", "#vQOPa38pGNeeHpcuWgdGX2w", "#vKsiy3enw4ihqiYVR2EaRf8", "#vxPYMAPb4zfgvsqMAq0F1HL", "#v341wTHAvfAszDBRIVtbDAb", "#vooC179GUYmhk1NUoUeRMlq", "#v10MhQ8GfUuXPPew0bjTozn", "#vBUY0eULDUU09q64demfxCq", "#vrNMVQ3UXsWMPfVWKsvpWg8", "#vZqIozEUp9LCuiODs2i7mKv", "#vzbwSVjAYn0bRWkiC5Muj5C", "#vbkxEPN9lPbB30a4jsBPzYl", "#vMxdz90POu0D9YgMLjq4DH3", "#vuCni6P6OnrB94L5cyBSpl3", "#vJSRzEhs77zILaMt6Sy0pMN", "#vYkBz5A9LbYLDyIh3gskbbl", "#vibhHqq9DeEvdzcLIZKNNz0", "#vZZ5K9156z6AGdtQum7cZ59", "#vaWaBS8y33ubwzb0KOpvMOc", "#vlb7c7YDmUeclLLOdamWvvq", "#vIOxJ8gUbNioVFL94kTKkME", "#vZdjJ9QO32JA1Ppu8rU8VUY", "#vkDXxgPBT2Ssuchhugys6Dl", "#vtFAEQT7PdM516PZcMZFvnG"], "id": "book-of-nod-apocrypha", "kind": "book", "label": "The Book of Nod: Apocrypha"}, "entities": {"#v0U6BORAaNacxrL3d38joOa": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Other Noddists look to you for insight and interpretation on the texts, and your theses on the subject are regarded as must-reads. You have exchanged correspondence with Noddist experts on finer points of lore. Once per story, you may derive a fact or prophecy from the Book of Nod that your character can apply to sway a decision, automatically succeeding at a Persuasion test at the Storyteller’s discretion.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#v0U6BORAaNacxrL3d38joOa", "key": "Noddist Master", "name": "Noddist Master", "parent": "#vIOxJ8gUbNioVFL94kTKkME", "props": [{"name": "Rating", "type": "INTEGER", "value": 5, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#v0ZxVGb4nxT2wKHlLrvdoBr": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vPZ5VdtH4OQ9RG8ISIh6aFE"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#v0ZxVGb4nxT2wKHlLrvdoBr", "key": "Level 3", "name": "Level 3", "parent": "#vaWaBS8y33ubwzb0KOpvMOc", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v10MhQ8GfUuXPPew0bjTozn": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Beware the Cainite who forgets his Curse, As to dream of mortal harmony. For all his cities will become ash And all his dreams shall be scattered to the winds A new enemy attends him now, The childer of his arrogance Twice born, thrice reborn, hungry for death Nurtured on devoured souls Savoring war as substance.\n\nHis children will be reborn from the ashes, The blood shall call them forth, Even from the land of shadows, From ashes they shall rise and walk again. So let none of the faithful fear death, Zillah’s tears shall nourish them, Blood of the Second Generation, Shed in the sorrow for the loss of her brothers. So shall the faithful become Zillah’s childer, And share in Caine’s triumph, And rule at their Father’s side.\n\nCaine be thy paragon thou shalt emulate or surpass, not worship. No end be served when thou crawls and grovels at thy Dark Father’s feet. Thy hierarchy and elders’ writ enforces frailty. Caine is thy Father, yet Caine be elder, and due subject of thine rebellion. As Caine rebelled, thou shalt rebel. Understand thy form and role under God, embracing thy predatory role, for it be divine. The predator doth not swallow pride and accept naught as elder deigns it so. Weakness be imposed on thee. For thee to surpass Caine, thou shalt study Caine and surpass all weakness. The Path of Caine leadeth us to rightful divinity. Strength be the core of all Cainites. Thou must consume the weak to become strong.\n\nThe Amaranth be a single path, yet not thy single journey. Let the snake, spider, and crocodile be roles that guide. Eschew the fury of the wolf, lion, and bear. The studious predator be thine model.\n\nAnd then the Dragon plundered Kupala’s mantle As he had been led to do And wore it as his own Ruling the land between the rivers And every place he strode As was His will Yet it forever remained a bitter veil Stolen and ill-fitting", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-apocrypha.ttrpg", "form": "DEF", "guidance": [], "id": "#v10MhQ8GfUuXPPew0bjTozn", "key": "Uncatalogued Fragments", "name": "Uncatalogued Fragments", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v1D5o6cfcTwstmoImkLPxFy": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "An elder vampire known to possess the tablet and other Noddist artifacts has gone missing. Their wisdom kept the peace between the city’s most powerful Kindred and their absence threatens to unravel everything. Were they murdered by hunters, seduced by an old rival, or did they succumb to the Beckoning? Whoever holds the tablet could gain great status with the Church of Caine and play a vital role in deciding who rules the city in the future.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#v1D5o6cfcTwstmoImkLPxFy", "key": "The Elder", "name": "The Elder", "parent": "#vitDdkZYIFZc2irxtkOUShR", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v341wTHAvfAszDBRIVtbDAb": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "In the beginning there was only Caine. Caine who murdered his brother out of anger. Caine who was cast out. Caine who was cursed forever with immortality, and A lust for blood. It is Caine from whom we all come, Our Sire’s Sire. For the passing of an age, he walked in solitude, In loneliness and suffering. For an eon he remained alone. But with the passing of memory so did depart a measure of his sorrow. One day he returned to the world of man, To the world that his brother’s children had created. He returned and he was made welcome. The people saw his power, they worshiped him, And made him King of their great City. The first City, by the name of Enoch. Though he became ruler of a mighty nation, he was still alone, For none were as he. His sorrow grew once again. Then he committed another great sin, for he beget Progeny. Of which there were only three. But from them came more Progeny, his grandchildren, And then Caine said, “An end to this crime, there shall be no more.” And as Caine’s word was the law, his Brood obeyed him. The city stood for many passings of the ages, And become the center of a mighty Empire. But then came the Calamity, a great Flood that washed over the world. The City was destroyed, And its people along with it. Again Caine fell into great sorrow and went into solitude, Becoming as a dog amidst the wastes, And leaving his Progeny to their own ends. They came to him and begged him to return, To help them rebuild the City. But he would not come with them, Saying that the Flood had been sent as punishment For his having returned to the world of the living And subverting the true law. So they returned alone lo what mortals were left And announced that they were the new rulers. Each created their own Brood, In order that they might claim the glory of Caine,\n\nYet they did not have his wisdom or restraint. Between them came a great war, the Elders against their Children, And the Children slew their parents. The rebels then built a new city And brought to it 13 tribes. It was a beautiful city and its people worshiped them as gods. They created new Progeny of their own, The Fourth generation of Cainites. But they feared the Jyhad, And it was forbidden for those Children To create others of their kind. This power their Elders kept for themselves. When a Childe was created, it was hunted down and killed, And its Sire with it. Though this city was as great as Caine’s, eventually it grew old, As do all living things, it slowly began to die. The gods at first did not see the truth, And when they at last looked about them it was too late. Their city was destroyed and their power extinguished, And they were forced to flee, their Progeny along with them. But many were killed in the flight, for they had grown weak. With their authority gone, all were free to create their own Broods, And soon there were many new Kindred Who ruled across the face of the Earth. But this could not last. Over time, there came to be too many of the Kindred, And then came fighting between them once again. The Elders were already deep into hiding, For they had learned caution. But their Children had founded their own cities and Broods, It is they who were killed in the great wave of war. The war was so total that there are none of that Generation To speak of themselves any longer. Waves of mortal flesh were sent across continents In order to crush and burn the cities of the Kindred. Mortals thought they were fighting their own wars, But it is for us that they spilt their blood. We have special memories of Odysseus, Xerxes and Alexander. Once this war was over, All of the Kindred went into hiding from one another And from the humanity that surrounded them. It is in that hiding which we remain today, For the Jyhad continues still.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-apocrypha.ttrpg", "form": "DEF", "guidance": [], "id": "#v341wTHAvfAszDBRIVtbDAb", "key": "Tale of the First City", "name": "Tale of the First City", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v3ImjZpqk9Ua4micjboUWXj": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "The Book of Nod has conflicting messages concerning werewolves. In some sections it seems to call them kin to the Gangrel and advises Kindred to leave them be as they can be dangerous enemies. In other places, such as among the Proverbs, the text advises vampires to “feast” upon the blood of the Moon Beasts. The Chronicle of Secrets implies that the rise of a great Lupine threat will be one of the many signs of the coming Gehenna, though a few Noddist scholars refute this interpretation and think the text speaks of a forgotten enemy instead. When a nearby city’s Court is completely destroyed by savage monsters under a blood red moon, the few survivors are quick to blame the Lupines. While the refugees and their resources are initially welcomed, it soon becomes clear that whatever wiped out their Court has followed them to their new home. Is this an early sign of Gehenna? Or is there a darker secret following these Kindred?", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#v3ImjZpqk9Ua4micjboUWXj", "key": "The Lupines", "name": "The Lupines", "parent": "#vgavXm3UCi00e2LIJBWnhGz", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v59kZXILX7Km38BIdeqOO9u": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "When Tremere committed diablerie on Saulot, the sire of all Salubri smiled. Once per story when witnessing another Kindred perform an action, you can ask the storyteller what their motivation was for doing so.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#v59kZXILX7Km38BIdeqOO9u", "key": "Saulot’s Smile", "name": "Saulot’s Smile", "parent": "#vkDXxgPBT2Ssuchhugys6Dl", "props": [{"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#v5Vae038Ro11NKDSWSRJmyh": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "When the Third Generation eventually rise, you know that most of Caine’s errant childer will be destroyed. So, killing another vampire in the name of the Antediluvians just makes their job a little easier. Once per story, when using a weapon or power that inflicts Aggravated Health damage on a vampire, your attack inflicts two additional damage, and you don’t need to roll to resist frenzy if that weapon or power involves fire.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#v5Vae038Ro11NKDSWSRJmyh", "key": "Kill Thy Brother", "name": "Kill Thy Brother", "parent": "#vtFAEQT7PdM516PZcMZFvnG", "props": [{"name": "Rating", "type": "INTEGER", "value": 5, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#v7YWG63wCedVlJCqG9ecUpP": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vg95RNGbQU9LKfvccTQNJY4"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#v7YWG63wCedVlJCqG9ecUpP", "key": "Level 1", "name": "Level 1", "parent": "#vibhHqq9DeEvdzcLIZKNNz0", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#v9cYn1buu7iDJPicK7e9YxQ": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "While Saulot’s words were gentle, his actions are said to have spurred on conflict between the Salubri and Tremere. You have learned to defend from these forces. Once per session gain two bonus dice when resisting Auspex, Blood Sorcery, Dominate, or Oblivion powers..", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#v9cYn1buu7iDJPicK7e9YxQ", "key": "Prolonged Conflict", "name": "Prolonged Conflict", "parent": "#vkDXxgPBT2Ssuchhugys6Dl", "props": [{"name": "Rating", "type": "INTEGER", "value": 2, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#v9fVpoR0cMxlR4rOXh4jdw9": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "A young coterie claim they have discovered the first steps on the path to Golconda in the ruins of Enoch, the lost city where Caine ruled. They’ve been scouring the world for Noddist texts and believe Caine’s tale of the angels can unlock the suspire, the last step into Golconda. Even if these Kindred are telling the truth, rumors spread that they have stolen the texts by murdering elders and Noddist scholars. Others believe their claim to Golconda is a ruse, and that they serve unknown masters or simply wish to dupe other Kindred into their scheme for money and clout. Most alarmingly, they are willing to trade Enoch’s location for the last texts they need to reach Golconda. A secret no Noddist scholar would be willing to pass on. Even if the players’ characters are not Noddists, they will have to find a way to profitably navigate this scheme before they find their allies, mentors, and rivals increasingly embroiled in the needs of these Golconda grifters.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#v9fVpoR0cMxlR4rOXh4jdw9", "key": "The First City", "name": "The First City", "parent": "#vEi8rlfjLZcyj5inOebULCG", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vAWzixK5T8jcNi7o1SlVYsm": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "The charlatans and demagogues of millenarian cults rely on charisma and their followers’ desperate need for someone else to provide answers, direction, and justification for their dark indulgences. Such self-deception is hard to overcome, but you know how to shatter their illusions and tear apart the foundations of their faith. Once per story for a scene, while socially interacting with you, cult members do not benefit from any dots in Status they may have within their own cult. If they are unable to overcome you in a conflict, they lose any such Status dots for the rest of the story as you shake the cult’s faith in them to the core.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vAWzixK5T8jcNi7o1SlVYsm", "key": "Cult Breaker", "name": "Cult Breaker", "parent": "#vZdjJ9QO32JA1Ppu8rU8VUY", "props": [{"name": "Rating", "type": "INTEGER", "value": 4, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vBUY0eULDUU09q64demfxCq": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Aristotle collected and rejected many proverbs over the ages, below is a sample of these that, ultimately, were not deemed authentic to the proverbs section of the Book of Nod:\n\nWhen the Ventrue leave, check your lands and servants. When the Brujah leave, check your defenses. ▪ Only a Nosferatu truly understands what beauty is. ▪ Fear your enemy most when he is silent. ▪ The more generous a Setite appears, the more wary you should be of accepting his gifts. ▪ Treasure those who guard you, who bear your blood as their strength. Protect them from danger, and cherish them as your own. For without them you are naked before the sun and helpless before your enemies. ▪ Hunt the shadow-sleepers Think not on fear or hate Hunt them for blood for Kindred’s sake. ▪ They must not awaken Slay the one and there shall not be a one when the sun sets. ▪ When love and hate turn strange And magpies filch the hours And Judas limbs betray Know you are a figment A shadow-sleeper’s dream Remember, remember Dreams die when sleepers wake Remember, remember for Kindred’s sake. ▪ Seek not the blood of thine own Elder.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-apocrypha.ttrpg", "form": "DEF", "guidance": [], "id": "#vBUY0eULDUU09q64demfxCq", "key": "Proverbs", "name": "Proverbs", "parent": null, "props": [{"items": [{"value": "The strong live by their own wages; the weak by the wages of their children.", "vk": "scalar"}, {"value": "Writing is the mother of eloquence and the father of artists.", "vk": "scalar"}, {"value": "Friendship in days of prosperity is servitude forever.", "vk": "scalar"}, {"value": "Let your family be as a tree: prune the weakest branches that the whole may be strong.", "vk": "scalar"}, {"value": "If you wish a secret to be known, tell it to a Toreador.", "vk": "scalar"}, {"value": "Three things a Prince should never do, if he means to prosper: Anger the Brujah; Embarrass the Ventrue; Ignore the Nosferatu.", "vk": "scalar"}, {"value": "In the darkness there is no rainbow.", "vk": "scalar"}, {"value": "The best way to defeat an enemy is to outlive him.", "vk": "scalar"}, {"value": "When the elders leave, it is time to fear.", "vk": "scalar"}, {"value": "If you must see love embraced, let it be done by your sire.", "vk": "scalar"}, {"value": "Nothing is more dangerous than a bored elder.", "vk": "scalar"}, {"value": "Every Cainite is a pawn on someone’s chessboard", "vk": "scalar"}, {"value": "Do not gamble with the Beast, for in the end it always wins.", "vk": "scalar"}, {"value": "Give a Ventrue a crown and he will be content.", "vk": "scalar"}, {"value": "When you think you understand an elder’s motivation, That is the time to start worrying.", "vk": "scalar"}, {"value": "To find the greatest darkness, seek within.", "vk": "scalar"}, {"value": "Never underestimate women. Once Embraced, they make the fiercest predators.", "vk": "scalar"}, {"value": "The safest way to assuage the rage of an elder is to amuse him.", "vk": "scalar"}, {"value": "When the Ravnos leave, check your purse.", "vk": "scalar"}, {"value": "Embrace not Love, for Love in My Embrace will grow cold, wither, and die.", "vk": "scalar"}, {"value": "Thou shalt not Emrbace love.", "vk": "scalar"}, {"value": "Never forget your Sire’s Sire, Caine the Wanderer.", "vk": "scalar"}, {"value": "In quiet, you will know beauty, in beauty you will know truth, in truth you will know love, in love, you will know quiet.", "vk": "scalar"}, {"value": "Beware those who walk without a clan, for they will be our undoing. ■", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vBdgOVLChhUbpHKKb7BqxgM": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "There is no greater crime than consuming another Kindred’s very essence. This is a common refrain among those aged Cainites most likely to be on the menu. While the cannibal Noddists of the Sabbat seem to exult in “eating the heart’s blood,” the Book of Nod itself is quite clear in its admonitions. The fall of Enoch and the clan banes are portrayed as the foul fruit of diablerie and Caine’s wrath against those who would devour their own. Despite these dire warnings, diablerie remains a singular temptation among many Kindred, perhaps more so than ever as elders become rare and the strength of the young and thin-blooded grows. When the domain’s last elder goes missing, few accept that those who so long resisted the Beckoning would abandon the domain without a farewell. Their progeny quickly become the prime suspects, but without any of the obvious marks of diablerie upon them, the truth will require careful investigation. Have these wayward childer discovered a way to hide the telltale signs? Or are they the victims of a plot to see them blamed for the crime of another?", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vBdgOVLChhUbpHKKb7BqxgM", "key": "“Watch your own Childer: on the lips of all is the honey-taste of Diablerie.”", "name": "“Watch your own Childer: on the lips of all is the honey-taste of Diablerie.”", "parent": "#vb5xQtoAr5aIf6YLCdZAUOq", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vCMSpHcrtnlbF5maXfpl3bU": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Despite the dangers of the Second Inquisition, a movement has emerged among a group of Brujah and thin-bloods advocating for the dismantling of the Masquerade. These zealots cite the words of Caine and the role of mortals in the city of Enoch. While this idea has outraged many Kindred in the city, it has found some supporters among the Anarchs, a few autarkis, and especially among those vampires who holding onto the myth of Carthage. According to legend, in that ancient city mortals willingly gave their blood to their Kindred benefactors. These zealots believe that they can exist among mortals openly if they have enough support. While they have yet to break the Masquerade themselves, the dangers of their message is obvious. That no one in authority has moved against them in force is as much of a mystery as their origins.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vCMSpHcrtnlbF5maXfpl3bU", "key": "The Utopians", "name": "The Utopians", "parent": "#vxt9FOsscR0jzHVxeS7AtbP", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vDr2UJgCDd2fg7pHCVVTHmR": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "The wisdom of the ancients is crucial for dealing with the end times. Is this Gehenna? Have we already wakened the Antediluvians? How can we even ask these questions without reference to the Book of Nod!\n\nYet so many of the younger Kindred Embraced in these squalid nights ignore the stories of Caine, Lilith, Enoch and the first nights.\n\nWe hear such ridiculous notions posited as our origins, with no other source than the merest supposition of a weak-minded fool.\n\nIs the Book of Nod the truth? Of course not. Any historian can tell you that when you try to understand what happened in ages past, there are no absolute truths. There are just sources and interpretations of varying credibility.\n\nI have the sources. The fragments, the scraps of parchment, the words of Kindred from ancient nights. These words echo through the centuries until they reach us, granting wisdom and clarity in the midst of confusion and ignorance.\n\nYet these brutish Anarch oafs or grasping Camarilla functionaries show no interest in my work. I should be lauded, feted in Elysiums across the world! Have I worked these endless nights for naught? Why are our kind so quick to ignore the lessons of history?\n\nAt least in my home city of Paris there are a few enlightened souls who understand the importance of my work, among them the Prince.\n\nThe willfully ignorant rabble comprising our Kindred in the modern nights will not win. The truth will go out, one way or another. Or a truth, anyway. Such is the nature of any inquiry into the past, even for those of us who have existed for so much of it.\n\n*\n\nThe Book of Nod? I heard someone talk about it. I was busy enjoying their Blood so I wasn’t paying attention. Why would you talk about something like that at such a private moment? And anyway, I have my own theories about vampires. Where we come from. I think it’s secret government experiments. Or we’re mutants! Or maybe it’s all a delusion. Only I don’t think a delusion can make our Blood taste as delicious as it does!\n\n**\n\nHis Blood is within us all! The Caine we read about in ancient tomes, in the Book of Nod, needs nobody to believe in him. What use is belief when his power is present in each and everyone of us!\n\n***\n\n—Vida Moreno, a Church of Caine priest\n\nTrying to write the history of the Kindred is more difficult than you’d think. The Masquerade means that troves of diaries and letters have been burned as potential risks. Elders lie when asked about the nights of antiquity, or misremember events to their own advantage.\n\nThe Book of Nod is a collection of fragments and scraps telling the legendary origin of the Kindred. Whether it’s all true or not it’s hard to say. But it is a fact that many vampires across the centuries have taken the stories in the Book of Nod seriously. It affects the Kindred whether they believe it to be literally true or not.\n\nKindred scholars of the Book of Nod are often called *Noddists*. They wish to find more fragments, determine the authenticity of the current text and find proof of whether it’s all true or not. There’s an abiding fantasy that one night, a newly awakened methuselah might confirm it one way or another, although this has yet to happen.\n\nAnd methuselahs are liars, the same as any other vampire.\n\nThe Book of Nod occupies a paradoxical place in modern vampire culture. The legions of recently Embraced Anarchs trying to figure out their unlives don’t know anything about the myths of Caine. The Book of Nod holds no significance to them. Yet at the same time, the Church of Caine has a presence in many domains, turning the old stories into a template for worship. In their hands, the Book of Nod is not just antiquated ideas but the basis for a real vampiric faith.\n\nThis booklet contains a collection of prompts based on the different chapters of the Book of Nod (Chapter 1). You can use them to make the book part of your chronicle. The prompts are followed by texts related to Kindred Mythology (Chapter 2), Kindred law (Chapter 3), and mechanics including Blood Sorcery Powers and Oblivion Ceremonies, and Loresheets related to Noddist lore (Chapter 4). ■", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#vDr2UJgCDd2fg7pHCVVTHmR", "key": "Introduction", "name": "Introduction", "parent": null, "props": [{"name": "Epigraph", "type": "STRING", "value": "—Aristotle deLaurent in an unsent letter —Dee, a Brujah neonate", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vECoTfGtZxl1G8dGbjh70mG": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vLQYKp58i9WRrgem8xndrZ1"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vECoTfGtZxl1G8dGbjh70mG", "key": "Level 2", "name": "Level 2", "parent": "#vibhHqq9DeEvdzcLIZKNNz0", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vEi5BpujYMW41UIz1xlUJWO": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Introduction: How to Use The Book of Nod The Book of Nod is not designed to be the definitive book on the nature of vampires and their founder, Caine. There are no game mechanics within. The reason behind this is that The Book of Nod is meant to be 100 percent setting material. Ideally, Storytellers will use The Book of Nod as a prop in either their Masquerade Mind’s Eye Theatre game or their Vampire: The Masquerade chronicles.\n\nThey may also use it to seed their games with an authentic culture: the culture of the Antediluvians which filters down from Caine himself. Want to make an Elder seem ancient and ultra-conservative? Have him quote from The Chronicle of Shadows. Want to give players the sense that they are close to the Antediluvians? Have them find a tablet with a fragment of the Chronicle of Caine on it. Want to scare them with threats of Gehenna? Have a Malkavian quote The Chronicle of Secrets to them.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#vEi5BpujYMW41UIz1xlUJWO", "key": "The Introduction to the Original", "name": "The Introduction to the Original", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vEi8rlfjLZcyj5inOebULCG": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vXvGzV4dpKXPJQSlmDTHWZ1", "#vZmEIZw0p92bUwbd0jp3bbz", "#v9fVpoR0cMxlR4rOXh4jdw9", "#vxSToEhGvCkb9l6m34RMw5W"], "choices": [], "desc": "The Book of Nod opens with The Chronicle of Caine, exploring the origins and early trials of the first vampire. Written from the perspective of Caine himself, these scrolls are particularly coveted by Noddists who wish to gain a deeper understanding of the father of all Kindred. Among those in the know, the most high-profile Noddist researcher is the Malkavian Aristotle de Laurent, but of course among the fractious Kindred he has his detractors.\n\nMany hope to get their hands on an authentic scroll in the hopes of noticing something that de Laurent missed or misinterpreted. Some clue that can either unravel the text as a hoax or prove its provenance beyond a shadow of a doubt. The Church of Caine, a Kindred cult of Noddists with a growing influence in the Camarilla, is particularly interested in anything that can cement their claims that Cainites can trace their roots to the stories of Caine.\n\nThe Bahari also have a keen interest in these texts as they search for clues to why Lilith chose to aid Caine when he was lost in the Land of Nod. The following story prompts focus on plots that use the scrolls to unearth the secrets of the vampiric condition and its origins.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vEi8rlfjLZcyj5inOebULCG", "key": "The Scrolls", "name": "The Scrolls", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vEynS7akYBESS2E4B4QiFOF": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Scour Secrets appears in the *Players Guide* and Shape the Sanguine Sacrament in *Winter’s Teeth Volume 1*.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vEynS7akYBESS2E4B4QiFOF", "key": "Note", "name": "Note", "parent": "#vYkBz5A9LbYLDyIh3gskbbl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vIOxJ8gUbNioVFL94kTKkME": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vWdk86wriiePrNcTEfVeYj7", "#vq6p8A8F9LKpUkivE0qzDvW", "#vXw6oF36FnnfnaPdUP9eY2v", "#vgwcamkAuaVNTLcLFCV5TJy", "#v0U6BORAaNacxrL3d38joOa"], "choices": [], "desc": "The Book of Nod collects oral histories, text fragments, and other media detailing the history of Caine and his childer, with additional poems and prophecies regarding Gehenna and the Final Nights. Its author — or authors — are unknown, though many Kindred believe Caine, Malkav, and Saulot contributed significant portions of the text. The stories and fragments have been carefully passed down through the generations; those who own physical pieces of the book take great pains to ensure they don’t end up in non-Cainite hands. The Book of Nod also provides the theological basis for the Sabbat’s worship of Caine.\n\nsome Kindred doubt its veracity and view it as the work of Carthaginian scholars. The Chronicle of Secrets is the shortest and most enigmatic section. Its highly symbolic passages describe the author’s visions of Gehenna. Some Noddists have dedicated their entire unlives to attempting to interpret the predictions and apply them to their modern nights. Additionally, some scholars view the Erciyes Fragments as another version of Caine’s story, while others dismiss the Fragments as apocryphal and relegate mention of them to a footnote in their dissertations, if they’re acknowledged at all.\n\nThe Book of Nod’s collectors, translators, and editors have introduced myriad inconsistencies and contradictions over the millennia, and no two scholarly analyses ever completely agree on its true content. Many among the Camarilla denounce the book and ban, confiscate, or destroy any related texts they discover their fledglings passing around.\n\nThe first and largest section of the book, the Chronicle of Caine, recounts the tale of the first vampire, his childer, and the rise and rebellion of the Antediluvians. The Chronicle of Shadows lays out a series of laws attributed to Caine, though", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vIOxJ8gUbNioVFL94kTKkME", "key": "The Book of Nod", "name": "The Book of Nod", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": "Loresheet", "typeHash": "#vtm5Loresheet0000001"}, "#vJSRzEhs77zILaMt6Sy0pMN": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Being a Declaration of Principles for the Self-Governance of the Kindred of the Free State.\n\nWe, the Kindred of the Free State, do hereby declare that we and our progeny, and all Kindred who choose freedom over oppression and liberty over tyranny, of all clans and generations, have as an inherent part of their being the spiritual substance called libertas, or Free Will. We further declare that, as we have freed ourselves from the bonds of mortality, so must we free ourselves from the forces that would rob us of our libertas. Not only must we continue to struggle on our own behalf, but on behalf of our brothers and sisters who continue to be robbed of their libertas by oppression, ignorance and fear.\n\nThe Anarch Free State is the political expression of that struggle. In choosing to free ourselves from political tyranny, we have also chosen to embrace our own libertas and that of our brother and sister Kindred everywhere.\n\nFor these reasons we, the Kindred of the Anarch Free State, meeting this night in solemn convocation, do hereby pledge ourselves to the following principles:", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-kindred-laws-and-traditions.ttrpg", "form": "DEF", "guidance": [], "id": "#vJSRzEhs77zILaMt6Sy0pMN", "key": "The Status Perfectus", "name": "The Status Perfectus", "parent": null, "props": [{"items": [{"value": "1. We declare ourselves to be free and independent, owing allegiance to no creature and no organization. 2. We declare our ability to rule ourselves, with no prince, no primogen and no other ruler other than that we choose for ourselves. 3. We declare our kinship with oppressed Kindred everywhere and offer a home to all Kindred of all generations and clans who will agree to dwell in harmony with us. 4. We further accept our responsibility to our oppressed brothers and sisters everywhere and pledge to assist them at all times and in all places in their own struggle for the freedom that we declare to be the birthright of all Kindred, from now until the end of time. 5. We recognize our responsibility to maintain the Masquerade, and we pledge to protect and defend it. 6. We establish this Status Perfectus and recognize its duty to all Kindred. ■", "vk": "scalar"}], "name": "Steps", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vKsiy3enw4ihqiYVR2EaRf8": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "And when She made preparation to return, the world broke in two. The Childer of Caine on one side, The Childer of Lilith on the other, And it was Gehenna. They named her Shaal for her questions, Though her names were many and maddening to hear. The Childer’s Childer recognized opportunity in chaos. Arikel sought unity, Ashur sought divinity, Loz sought war, Malakai sought peace. Malkav sought wisdom through bargain with Ilyes, Who told his brother, “Your wisdom shall come with centuries of madness, Allowed to purify into something whole, The vitae of the mad will pour afresh in years to come. The old forms shall wither on the vine, And declare the end times. Only the children of Enoch, Shall see the new age.” The breaking of the world near complete, The sacrifice of a generation prevented Shaal’s Gehenna. She would try again, And again. Each time a new sacrifice, More burdensome than the last. Malkav’s blood shall pour forth, The Book of Chaos in the Underworld written, To prevent Shaal’s Gehenna. Sargon’s get will understand, But they will not share their understanding. The Brides of the Dragon will understand, But their fee will be high. Her hatred is as the phases of the moon. Gehenna follows the path of Her ire.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-apocrypha.ttrpg", "form": "DEF", "guidance": [], "id": "#vKsiy3enw4ihqiYVR2EaRf8", "key": "Shaal Fragment", "name": "Shaal Fragment", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vL19NKU3WmGWv9lDgIAOmiL": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "One Rouse Check", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vL19NKU3WmGWv9lDgIAOmiL", "key": "Cost", "name": "Cost", "parent": "#vLQYKp58i9WRrgem8xndrZ1", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vLQYKp58i9WRrgem8xndrZ1": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vL19NKU3WmGWv9lDgIAOmiL"], "choices": [], "desc": "The Blood Sorcerer unleashes rivulets of their Blood primed to search for information on a subject of their choosing. The Blood washes over the object of their search, allowing the Blood Sorcerer to investigate vast amounts of text and volumes in a matter of minutes. The object investigated bears a telltale bloodstain thereafter.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vLQYKp58i9WRrgem8xndrZ1", "key": "Scour Secrets", "name": "Scour Secrets", "parent": "#vECoTfGtZxl1G8dGbjh70mG", "props": [{"name": "Discipline", "type": "STRING", "value": "Blood Sorcery", "vk": "scalar"}, {"name": "Level", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "System", "type": "STRING", "value": "The user makes the Rouse Check and tests Intelligence + Blood Sorcery against a Difficulty set by the Storyteller: anything from 2 for a single letter in a regular office up to 5 for encrypted information hidden in a vast library. If the information has been supernaturally concealed the Difficulty increases further. The time spent depends on the size of the area to be searched: A single room might be scoured in minutes, while a library requires hours, if not the whole night. Additionally, the power does not impart the ability to parse the information if it comes in an unknown language or in a cipher. If the knowledge sought is stored in non-written formats, such as painting, music, or on old floppy disks, the power works at the Storyteller’s discretion, though the Difficulty is likely higher.", "vk": "scalar"}, {"name": "Duration", "type": "STRING", "value": "One night or until the information is found or the search comes up short, whichever comes first.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Discipline Power", "typeHash": "#vtm5DisciplinePower1"}, "#vMK72TyfmudeRW48CTrGxkI": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "The version of the Book of Nod compiled by Aristotle de Laurent is the one a modern vampire is most likely to see. However, de Laurent had his own prejudices and opinions as to what should be included. There are other versions of the book as well, with a slightly different set of texts.\n\nThe question of translations is an important issue of its own. All of the known fragments in the Book of Nod have been translated and re-translated many times across the centuries. Original meaning may have been obscured or even reversed.\n\nSimilarly, the various petty squabbles of Noddists through time have influenced the content of the book. Sometimes feuds between Kindred academics have turned deadly over something as trivial as the proper translation of a single expression.\n\nAnd of course, even though de Laurent has a magnificent collection of Noddist scrolls, manuscripts, stone tablets and other artifacts, some may still have eluded him.\n\nIn Chapters 3 and 4, you will find the apocryphal documents that can be found in *The Book of Nod Deluxe Artifact Edition*. ■", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vMK72TyfmudeRW48CTrGxkI", "key": "Apocryphal Texts", "name": "Apocryphal Texts", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vMNqGhg15Dx3FScwV7b8TUt": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "One Rouse Check", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vMNqGhg15Dx3FScwV7b8TUt", "key": "Cost", "name": "Cost", "parent": "#vPZ5VdtH4OQ9RG8ISIh6aFE", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vMxdz90POu0D9YgMLjq4DH3": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "I, [initiate’s name], hereby swear my everlasting loyalty to House and Clan Tremere and all its members. I am of their blood, and they are of mine. We share our lives, our goals and our achievements. I shall obey those the House sees fit to name my superiors, and treat my inferiors with all the respect and care they earn for themselves.\n\nI will not deprive nor attempt to deprive any member of House and Clan Tremere of his magical power. To do so would be to act against the strength of our House. I will not slay nor attempt to slay any member of the House and Clan except in self-defense, or when a magus has been ruled outlaw by a properly constituted tribunal. If a magus has been ruled an outlaw, I shall bend all efforts to bring such magus to justice.\n\nI will abide by all decisions of the tribunals, and respectfully honor the wishes of the Inner Council of Seven and the wishes of my superiors. The tribunals shall be bound by the spirit of the Code of Tremere, as supplemented by the Peripheral Code and interpreted by a properly constituted body of magi. I have the right to appeal a decision to a higher tribunal, if they should agree to hear my case.\n\nI will not endanger House and Clan Tremere through my actions. Nor will I interfere with the affairs of mundanes in any way that brings ruin upon my House and Clan. I will not, when dealing with devils, or others, in any way bring danger to the clan, nor will I disturb the faeries in any way that should cause them to take their vengeance on the House and Clan. I also swear to uphold the values and goals of the Camarilla, and I will maintain the Masquerade. Insofar as these goals may conflict with my goals, I will not pursue my own ends in any way that would endanger the Masquerade. The strength of the House and Clan Tremere depends on the strength of the Masquerade.\n\nI will not use magic to scry upon members of the House and Clan Tremere, nor shall I use it to peer into their affairs. It is expressly forbidden.\n\nI will train only apprentices who will swear to this code, and should any of them turn against the House and Clan, I shall be the first to strike them down and bring them to justice. No apprentice of mine shall be called magus until he first swears to uphold the code. I shall treat my apprentices with the care and respect that they earn.\n\nI concede to my elders the right to take my apprentice should it be found that my apprentice is valuable to an elder’s work. All are members of the House and Clan and valuable first to these precepts. I shall abide by the right of my superiors to make such decisions.\n\nI shall further the knowledge of the House and Clan and share with its members all that I find in my search for wisdom and power. No secrets are to be kept, or given, regarding the arts of magic, nor shall I keep secret the doings of others which might bring harm to the House and Clan.\n\nI demand that, should I break this oath, I should be cast out of the House and Clan. If I am cast out, I ask my brothers to find and slay me that my life may not continue in degradation and infamy.\n\nI recognize that the enemies of the House and Clan are my enemies, that the friends of the House and Clan are my friends, and that the allies of the House and Clan are my allies. Let us work as one and grow hale and strong.\n\nI hereby swear this oath on [current date]. Woe to they who try to tempt me to break this oath, and woe to me if I succumb to such temptation.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-kindred-laws-and-traditions.ttrpg", "form": "DEF", "guidance": [], "id": "#vMxdz90POu0D9YgMLjq4DH3", "key": "Old Tremere Code", "name": "Old Tremere Code", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vMzlmnq7vUjRMaYlS2T9KrS": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "A group of mortal hunters have destroyed a Noddist vampire scholar and have stolen their cache of occult texts. They’ve begun to decipher the Noddist scrolls in their possession and learned a great deal about vampire society and the power of the Blood Bond and the Kiss. Most shockingly they’ve used this knowledge to identify and shadow ghouls back to their masters’ havens. Are they part of a larger organization? How many other hunters have they passed this knowledge on to? Killing them and recovering the stolen texts might not solve the larger problem. A savvy coterie of young Kindred might have to find a way to discredit them, or perhaps they could use what the hunters have learned to attack the ghouls of their own rivals.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vMzlmnq7vUjRMaYlS2T9KrS", "key": "The Hunters", "name": "The Hunters", "parent": "#vxt9FOsscR0jzHVxeS7AtbP", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vPZ5VdtH4OQ9RG8ISIh6aFE": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vst24rHGB1VFHUU0hrXmjij", "#vaFyAVAYnQ6nQh2mRaZC2yW", "#vMNqGhg15Dx3FScwV7b8TUt", "#vVPhlY8vuJvN9HQtADmjxS6"], "choices": [], "desc": "This Ceremony allows the Kindred to glean skills and abilities from the head or skull of a corpse. The information gleaned represents the spiritual echoes of the deceased. Their spirit or will is not invoked.\n\nAt dawn, roll one die for each skill roll boosted: a failure on any of these dice indicates the skull or head dissolves to ashes as the Ceremony ends and it cannot be reconstituted by any means.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vPZ5VdtH4OQ9RG8ISIh6aFE", "key": "Wisdom of the Dead", "name": "Wisdom of the Dead", "parent": "#v0ZxVGb4nxT2wKHlLrvdoBr", "props": [{"name": "Discipline", "type": "STRING", "value": "Oblivion", "vk": "scalar"}, {"name": "Level", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "System", "type": "STRING", "value": "The cermonist must possess a skull or head. After rolling Resolve + Oblivion (Difficulty 2 for a mostly intact head, or 3 for a skull), the Kindred begins to glean knowledge from the deceased. The Storyteller will name one skill the deceased was most knowledgeable about in life (or unlife if a Kindred skull) and an additional skill per point of the margin of success. For the rest of the night, the user may draw upon the deceased’s knowledge: each time the user rolls one of the deceased’s skills, so long as they are still carrying their skull or head, they may add 2 dice to your dice pool. This only applies if the deceased had a higher skill rating than the user.", "vk": "scalar"}, {"name": "Duration", "type": "STRING", "value": "Until dawn or the head/skull is destroyed. ■", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Ceremony", "typeHash": "#vtm5Ceremony00000001"}, "#vQFxNTHo2vEHh2q1q8amYK7": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Manipulation + Blood Sorcery", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vQFxNTHo2vEHh2q1q8amYK7", "key": "Dice Pools", "name": "Dice Pools", "parent": "#vg95RNGbQU9LKfvccTQNJY4", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vQOPa38pGNeeHpcuWgdGX2w": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "I’ve been able to corroborate some of the apocryphal additions to the Book of Nod from interviews with our ancient kind. Of course, they’re arrogant and more trusting of their memories than they perhaps should be, but it’s still useful. If I have a primary text in the form of a manuscript and then find an elder able to recite it almost verbatim, it means the words didn’t flow from the pen of a modern fabricator. Although of course there have been many mythmakers among our kind in ages past as well.\n\nThe version of the Book of Nod compiled by Aristotle de Laurent is the one a modern vampire is most likely to see. However, de Laurent had his own prejudices and opinions as to what should be included. There are other versions of the book as well, with a slightly different set of texts. The question of translations is an important issue of its own. All of the known fragments in the Book of Nod have been translated and re-translated many times across the centuries. Original meaning may have been obscured or even reversed.\n\nSimilarly, the various petty squabbles of Noddists through time have influenced the content of the book. Sometimes feuds between Kindred academics have turned deadly over something as trivial as the proper translation of a single expression.\n\nAnd of course, even though de Laurent has a magnificent collection of Noddist scrolls, manuscripts, stone tablets and other artifacts, some may still have eluded him.\n\nBelow you will find a few sample apocryphal documents that can be found in *The Book of Nod Deluxe Artifact Edition.*", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-apocrypha.ttrpg", "form": "DEF", "guidance": [], "id": "#vQOPa38pGNeeHpcuWgdGX2w", "key": "Chapter 2: The Apocrypha", "name": "Chapter 2: The Apocrypha", "parent": null, "props": [{"name": "Epigraph", "type": "STRING", "value": "— Beckett, a Gangrel knowledge seeker", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vRMDbtSlj6PIs8rLb5TR2ov": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "A fanatical vampire warlord or popular Church of Caine demagogue threatens to burn the city to the ground. A horde of recently Embraced, bloodthirsty followers are only a few nights away. The bestial warlord claims they purchased the tablet from a respected Kindred, perhaps even the coterie’s Mawla, but was delivered a fake. Allowing such a key piece of vampire history to fall into the hands of such a creature would be a tragedy, but is it worth risking the Masquerade? Why would a supposed ally work with such a monster in the first place? Why risk such a dangerous vampire’s ire and what could they have offered to pay for something as priceless as the tablet?", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vRMDbtSlj6PIs8rLb5TR2ov", "key": "The Warlord", "name": "The Warlord", "parent": "#vitDdkZYIFZc2irxtkOUShR", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vUth8ILAjxzA2B34lEdXtfq": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Prophecy is at the heart of the Chronicle of Secrets, and few prophecies have been more true than that of the thin-bloods considering more seem to appear every night. If the Noddist scholars are to be believed then the Book of Nod predicts the coming of the thin-bloods and their weakened nature by several millennia. That the curse of Caine weakened from generation to generation had long been clear, but that it would break and cease to take root in Embraced mortals must have seemed absurd until the first of the duskborn came to be. When a thin-blood tattooed with the Chronicle of Secrets enters a domain uninvited they are quickly captured and executed by the local Prince. The tapestries made from their remains become the centerpiece at the Elysium, but when a blood-borne plague afflicts the court many wonder if they are somehow cursed. Is this sickness the mystical revenge of the tattooed thin-blood or another sign of Gehenna’s coming?", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vUth8ILAjxzA2B34lEdXtfq", "key": "The Prophecy", "name": "The Prophecy", "parent": "#vgavXm3UCi00e2LIJBWnhGz", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vVPhlY8vuJvN9HQtADmjxS6": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Resolve + Oblivion", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vVPhlY8vuJvN9HQtADmjxS6", "key": "Dice Pools", "name": "Dice Pools", "parent": "#vPZ5VdtH4OQ9RG8ISIh6aFE", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vVysMek36hJK0NUq8qANz5i": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "The city’s Nosferatu have quietly been disappearing and many of the more conspiracyminded Kindred have begun to fear the worst. None have been found destroyed and the few Nosferatu who remain are either unwilling or unable to shed any light on the situation. Is the domain under attack by a subtle foe, or have the Nosferatu stumbled upon something in their warrens and tunnels that’s too terrible to speak of above ground? Whatever the truth, the domain’s power brokers have taken on a siege mentality as they see the Nosferatu’s plight as an ill omen. Their perfunctory investigations have revealed nothing and they seem content to isolate themselves in their penthouses and gated communities until the danger passes. Kindred fear walking the streets as others of their kind begin to disappear. An outright revolt forms as common vampires become too afraid to feed and begin to band together as their paranoia grows. A savvy coterie could use this opportunity to gain goodwill among the less fortunate by finding the cause of the trouble. Or they could curry favor with the powers that be, by subverting any attempts to turn the city against them for failing to protect the less fortunate.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vVysMek36hJK0NUq8qANz5i", "key": "“The first to die in any Jyhad are Nosferatu.”", "name": "“The first to die in any Jyhad are Nosferatu.”", "parent": "#vb5xQtoAr5aIf6YLCdZAUOq", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vWJjY2DPrt0MqqoBEtabkaZ": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "You’re a proven investigator; you’ve exposed and taken down at least one Gehenna cult already, and shown your mettle in the eyes of the sects. Either the Camarilla or the Anarchs trust you as an expert on Gehenna cults. You wield three dots of Status while taking action to investigate or persecute a cult on behalf of that sect.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vWJjY2DPrt0MqqoBEtabkaZ", "key": "Faithful Bloodhound", "name": "Faithful Bloodhound", "parent": "#vZdjJ9QO32JA1Ppu8rU8VUY", "props": [{"name": "Rating", "type": "INTEGER", "value": 2, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vWdk86wriiePrNcTEfVeYj7": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "You are familiar with the broader concepts of the Book of Nod and some of the more commonly known prophecies. Once per story, add two dice to an Academics roll related to ancient Cainite history.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vWdk86wriiePrNcTEfVeYj7", "key": "Precis", "name": "Precis", "parent": "#vIOxJ8gUbNioVFL94kTKkME", "props": [{"name": "Rating", "type": "INTEGER", "value": 1, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vWuKRdyV5EMDBM6ST2q99L4": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "A local mortal band gets a lot of media attention when one of their songs goes viral and soon they’ll receive a large music deal. Unfortunately their lyrics make it clear that they know too much about Kindred society, making mention of “the Embrace”, “ghouls”, “the Kiss”, and “thin-bloods”. How the local vampires will handle this potential breach of the Masquerade becomes personal if a player’s character’s Touchstone or other Relationship-Map connection is a member. Not only could this potentially cause them to lose a vital asset, but their entire coterie may immediately be seen as the likely source of the Masquerade breach or they are forced to extreme lengths to silence their own Touchstone(s). Discovering where they learned about the Kindred could be the only way to prove their innocence. Perhaps one of their roadies is a Duskborn? Or they stumbled upon a vampire feeding in a heroin den and he became too talkative in his delirium? Or maybe they were given fragments of the Book of Nod by a rival coterie so as to frame the players’ characters?", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vWuKRdyV5EMDBM6ST2q99L4", "key": "“Let not the priest, poet, or peasant see you feed. Not one of them will leave it be.”", "name": "“Let not the priest, poet, or peasant see you feed. Not one of them will leave it be.”", "parent": "#vb5xQtoAr5aIf6YLCdZAUOq", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vXF1U7y60joQiPQuuCVtKaS": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Ashes to Ashes or Oblivion’s Sight", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vXF1U7y60joQiPQuuCVtKaS", "key": "Prerequisite Power", "name": "Prerequisite Power", "parent": "#viscyWuAhJJkgwEXbt9URVv", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vXXJV12zWBynC1FzNskLxKL": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vj9tAROWWpgzum6YwW0zyet", "#vg7bpLGQEjwHq9Ty6bHuNgj"], "choices": [], "desc": "Kindred sorcerers have learned to embed messages into their blood, or a vessel when feeding. Though there may be difficulties in sending the messenger to the recipient, the message is much less likely to be intercepted: this old art has come into vogue since the advent of the Second Inquisition.\n\nThe first person to consume the ensorcelled blood from the messenger automatically receives the message mentally if they are the intended recipient or possess A Taste for Blood. Any other imbiber must succeed on a Wits + Occult roll (Difficulty 3) to understand the message.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vXXJV12zWBynC1FzNskLxKL", "key": "Blood Apocrypha", "name": "Blood Apocrypha", "parent": "#veUtpjF3qUhhRkRXxEFHRIX", "props": [{"name": "Discipline", "type": "STRING", "value": "Blood Sorcery", "vk": "scalar"}, {"name": "Level", "type": "INTEGER", "value": 1, "vk": "scalar"}, {"name": "System", "type": "STRING", "value": "The Kindred encodes about one minute of speech into one Rouse Check worth of blood in a ritual bowl. The ritualist then designates one or more intended recipients of the message whose blood they have tasted. As part of the ritual, a Kindred, mortal, or beast messenger must consume the blood to transfer the message to their own body, otherwise the blood—and message—will rapidly sour.", "vk": "scalar"}, {"name": "Duration", "type": "STRING", "value": "One month plus another month for each point of the margin of success", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Ritual", "typeHash": "#vtm5Ritual0000000001"}, "#vXvGzV4dpKXPJQSlmDTHWZ1": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "A scholarly vampire genealogist returns to the Elysium after a long absence, claiming to have proven that the Kindred could not have originated from a single source. Their salons quickly become popular social events, but their conclusions undermine many Noddist myths and articles of faith. Local Camarilla traditionalists, zealous Noddists, and a few members of the Church of Caine have demanded they recant their research and some fear violence follows if they don’t. Perhaps some overlooked secret within the Chronicle of Caine could help them make their point? Or disprove their theory all together? Even if a young coterie is interested in the details of vampire theology, they could make a name for themselves by finding a novel solution or playing all sides for their own interests.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vXvGzV4dpKXPJQSlmDTHWZ1", "key": "The Researcher", "name": "The Researcher", "parent": "#vEi8rlfjLZcyj5inOebULCG", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vXw6oF36FnnfnaPdUP9eY2v": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "You’ve dedicated significant time and study to the Book of Nod, and are familiar with at least one complete version of the text. You can support your theories with quotes from that version and are aware of counterarguments or alternative interpretations. Once per session, add three dice to a Persuasion roll when debating the Book of Nod’s finer points.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vXw6oF36FnnfnaPdUP9eY2v", "key": "Scholar", "name": "Scholar", "parent": "#vIOxJ8gUbNioVFL94kTKkME", "props": [{"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vYkBz5A9LbYLDyIh3gskbbl": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vEynS7akYBESS2E4B4QiFOF"], "choices": [], "desc": "They’ve put me on the Red List just because I published the Book of Nod, broke the Masquerade and committed diablerie more than once. But it all serves a purpose, after a fashion. Trying to kill me is like trying to quiet the voice of destiny. Every attempt only adds to my name, even when I never sought to be infamous among our kind.\n\nI never sought for this to happen but it seems my name has been inscribed in the annals of our kind for the crime of perpetuating memory.\n\nThe lawbreakers are the ones whose legend lasts.\n\nLook no further than Caine himself!\n\nThis chapter details Discipline Powers, Rituals, and Ceremonies which connect to the themes in the Book of Nod: masters of Blood Sorcery and Oblivion search for—or create—texts and relics, and Noddists and other scholarly groups seek out the mysteries of the elders.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vYkBz5A9LbYLDyIh3gskbbl", "key": "Chapter 4: Disciplines", "name": "Chapter 4: Disciplines", "parent": null, "props": [{"name": "Epigraph", "type": "STRING", "value": "— Ayisha Jocastian, Malkavian neonate and publisher of a modern print edition of The Book of Nod", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vZZ5K9156z6AGdtQum7cZ59": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#veUtpjF3qUhhRkRXxEFHRIX"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vZZ5K9156z6AGdtQum7cZ59", "key": "Blood Sorcery Rituals", "name": "Blood Sorcery Rituals", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vZdjJ9QO32JA1Ppu8rU8VUY": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vZyLOpUHuYLsAhp3WZYa2mG", "#vWJjY2DPrt0MqqoBEtabkaZ", "#vp3t3qiM4qRZxhMbqiOxO6Y", "#vAWzixK5T8jcNi7o1SlVYsm", "#vrI72Z7noCpOxfFfpcPLkpR"], "choices": [], "desc": "Depending on whom you ask, Gehenna will soon befall the Kindred, or it’s happening *right now*, or it’s happened already and vampires are just play-acting in the crumbling ruins of their unlives while the world comes apart at the seams. While some deride the notion of Gehenna as an invention for duping the guileless, a feverish millenarianism has gripped many Kindred with the belief that these are indeed the Final Nights, one way or another. Blood cults and heresies spring up from the shadows in ever-growing numbers.\n\nThe creeds of these new blood cults come in a dizzying variety of hatreds, anxieties and hungers. The most successful spread their black wings from one city to the next, forming something like a cohesive doctrine even as feuding Kindred splinter off new schisms and heresies. Charting out the spread of such subversive elements requires an agile mind to keep track of the shifting tapestry, not to mention a strong stomach even by vampire standards. All too many Gehenna cults delve into stomach-churning practices.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vZdjJ9QO32JA1Ppu8rU8VUY", "key": "Gehenna Cults", "name": "Gehenna Cults", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": "Loresheet", "typeHash": "#vtm5Loresheet0000001"}, "#vZmEIZw0p92bUwbd0jp3bbz": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "An ancient structure is discovered beneath the city. The local Camarilla Prince has warned that anyone disturbing the structure will be subjected to the Blood Hunt and destroyed. The origin of the buried temple or edifice is unknown, but a rumor soon spreads it was built by a long defunct cult of vampires. Why is the Prince forbidding entry? Perhaps the worn scrolls found in the vicinity will give a clue?", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vZmEIZw0p92bUwbd0jp3bbz", "key": "The Ruins", "name": "The Ruins", "parent": "#vEi8rlfjLZcyj5inOebULCG", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vZqIozEUp9LCuiODs2i7mKv": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "**I. Covenant** “Thy blood makes thee my brood, crafted in my image. My curse is thine, and my salvation is thine. I stand before and above thee as god-regent. I am the way, my Traditions my covenant. Renounce me and Renounce all hope.” Thus spoke Caine.\n\n**II. Domain** Thou art its master, and all will respect this or suffer thy wrath. All will present themselves when entering, and thou shall protect them in turn. By right, thou art allowed to hunt within the bounds of thy domain, its blood thine own. Accept its responsibility, minister thy domain, and pay others the same respect thou expect.” Thus spoke Caine.\n\n**III. Progeny** “Thou shalt only sire another with the permission and blessing of thine elder. To create is the providence of those closest to me, for they shall be accountable. Break this, and both thee and thy progeny shall be slain.” Thus spoke Caine.\n\n**IV. Accounting** “Those thou create are thine own blood until release from thy charge. Until that moment, their sins, their blood and their punishments are thine.” Thus spoke Caine.\n\n**V. Destruction** “Forbidden art thou to spill the blood of another of thy kind who is elder. This right belongs only to the closest to me and none other. It is forbidden for those of weaker blood to rise against their elders. This is my final covenant.” Thus spoke Caine.\n\n**VI. Silence of the Blood** “Never shalt thou reveal thy true nature to those not of the blood. Doing so shall renounce thy claims to my covenants.” Thus spoke Caine.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-kindred-laws-and-traditions.ttrpg", "form": "DEF", "guidance": [], "id": "#vZqIozEUp9LCuiODs2i7mKv", "key": "Traditions of Caine", "name": "Traditions of Caine", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vZyLOpUHuYLsAhp3WZYa2mG": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Once per session when you begin investigating or researching the presence of a blood cult you’ve not previously used this lore for, the Storyteller gives you one free clue to help locate the cult or to understand their current plans.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vZyLOpUHuYLsAhp3WZYa2mG", "key": "Mark the Bloody Trail", "name": "Mark the Bloody Trail", "parent": "#vZdjJ9QO32JA1Ppu8rU8VUY", "props": [{"name": "Rating", "type": "INTEGER", "value": 1, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vaFyAVAYnQ6nQh2mRaZC2yW": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "The head or skull of the deceased, pure water and a small flame.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vaFyAVAYnQ6nQh2mRaZC2yW", "key": "Ingredients", "name": "Ingredients", "parent": "#vPZ5VdtH4OQ9RG8ISIh6aFE", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vaWaBS8y33ubwzb0KOpvMOc": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vzNHzSv0fWOtZNQ0uwf4tHs", "#v0ZxVGb4nxT2wKHlLrvdoBr"], "choices": [], "desc": "The Oblivion Discipline and its Ceremonies are fully detailed in the *Players Guide*.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vaWaBS8y33ubwzb0KOpvMOc", "key": "Oblivion Ceremonies", "name": "Oblivion Ceremonies", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vb5xQtoAr5aIf6YLCdZAUOq": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vVysMek36hJK0NUq8qANz5i", "#vBdgOVLChhUbpHKKb7BqxgM", "#vWuKRdyV5EMDBM6ST2q99L4"], "choices": [], "desc": "Aside from the Traditions derived from Caine’s laws, the proverbs found within the Book of Nod are arguably the most well-known parts of Noddist lore. Many are little more than stereotypes and common wisdom intended to guide a young Kindred in the intricacies of vampiric society, but a few are thought to speak of deeper truths regarding the Cainite condition. More than a few Anarchs have suspected that the proverbs are a late addition to the Book of Nod, meant to support Camarilla rule.\n\nUnlike many of the other maxims gleaned from the Book of Nod, repeating these proverbs is unlikely to raise too much suspicion in the Camarilla and may even be taken as a sign of an attentive and scholarly sire. Many Anarchs consider this kind of “schooling” a sure sign of Camarilla indoctrination. This also makes them useful to Noddists, Gehenna cultists, and Sabbat vampires who wish to seek each other out or communicate without exposing themselves to the uninitiated.\n\nMaking sense of a proverb is often less important than understanding the subtext present in the situation in which they are used. Is the speaker an elder or scholar? Or are they signaling their allies to action or nefarious deeds? The story ideas below expand on some of the most well-known proverbs as plot devices and how they can shape a domain’s response to challenge and danger.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vb5xQtoAr5aIf6YLCdZAUOq", "key": "Proverb Fragments", "name": "Proverb Fragments", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vbkxEPN9lPbB30a4jsBPzYl": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "**I. The Legacy of Trinity** Of three is the rule of Constantinople. Only those Three can voice their concerns and set upon this codex new laws. It is also the responsibility of the Three to ensure that the concerns of the Scions are heart.\n\n**II. The Legacy of Progeny** Only those of the Trinity are free to sire. Even the scion families must petition the three Quaesitors for permission to sire. Failure to do so results in destruction of the progeny and banishment of the sire.\n\n**III. The Legacy of Founding** Only the Three can bequeath domain, just as the First Three founded the city. Cainites are granted domain upon the Embrace, if they are to receive any at all, and are responsible for ensuring that the Codex of Legacies is enforced in their domains.\n\n**IV. The Legacy of Shadow** The Three are masters of the night, and hence must rule in darkness. They must be revered as divinities, but their true nature should never be revealed. Just as the nature of the Father, Sun, and Holy Ghost is unknown, so must that of the Trinity.\n\n**V. The Legacy of Ashes** The destruction of a family member is prohibited unless the Three condone it. Violation of this legacy results in a trial, after which Final Death is inflicted upon the offender. Those not of the families are not so protected from harm.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-kindred-laws-and-traditions.ttrpg", "form": "DEF", "guidance": [], "id": "#vbkxEPN9lPbB30a4jsBPzYl", "key": "Legacies of the Trinity", "name": "Legacies of the Trinity", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vcDUKD1QYqYA4eDNMxUJN2P": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Those aware of the age-old conflicts of the Salubri are on the lookout for signs of their recurrence. You can ask the Storyteller if an event or location shows signs of Salubri or Tremere influence. You can ask this question once per session.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vcDUKD1QYqYA4eDNMxUJN2P", "key": "Rumors and Signs", "name": "Rumors and Signs", "parent": "#vkDXxgPBT2Ssuchhugys6Dl", "props": [{"name": "Rating", "type": "INTEGER", "value": 1, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vdSSIxSLNyXOcdQxIJmsdLv": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "A young vampire approaches the coterie and claims they are part of a Noddist prophecy and that only they can decipher the secret hidden within the tablet. Perhaps the coterie is aware that the neonate is able to trace their lineage to a legendary vampire, or a Malkavian seer saw them in a vision, or they were Embraced under peculiar circumstances. Regardless of the stranger’s motives, Noddists, Bahari, and Gehenna cultists are now searching for the coterie and some would prefer the tablet’s secrets remain unknown. Is this an elaborate trap conjured up by the coterie’s rivals? An opportunity to ingratiate themselves with the Church of Caine? Or does Caine truly have a special role for them to play in the Gehenna War?", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vdSSIxSLNyXOcdQxIJmsdLv", "key": "The Neonate", "name": "The Neonate", "parent": "#vitDdkZYIFZc2irxtkOUShR", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vdfqNXU1pYhu6fGUtzSV77f": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "The Book of Nod is part of the cultural heritage of the Kindred. Some, like the faithful of the Church of Caine, take it seriously while others ignore it. Still, even the most secular Anarch has probably wondered at least once where vampires come from and why. This is the power of the Book of Nod: It cannot be verified or proven to be true, but it answers troubling questions. An unreliable answer is better than no answer at all, in the minds of many.\n\nAmong the Kindred, there are three major categories of vampires interested in the Book of Nod. The Church of Caine holds it as a holy text. Much of the worldview animating the Sabbat and motivating their bloody carnage follows the same mythical stories. The third group is the Noddists, Kindred scholars who seek to understand the nature, origins and history of vampires.\n\nAmong the rarefied ranks of the Noddists, there are three authorities of varying eminence: the Malkavians Aristotle de Laurent and Ayisha and the Gangrel Beckett. A Parisian elder, de Laurent is a writer, scholar and an antiquarian. He’s a protégé of the Prince of Paris, François Villon, which is probably why he’s been able to write down so much despite the danger to the Masquerade posed by such texts.\n\nBeckett is de Laurent’s adopted childe, a more active and dynamic researcher also of considerable age. He has persisted in arguing that the Book of Nod is an allegorical tale and not to be taken as the literal truth.\n\nAyisha is the youngest of the three and the most controversial, having been subject to a Blood Hunt in many Camarilla domains for her ideas concerning the transmission of knowledge through diablerie. She has also been a proponent of distributing the Book of Nod more widely among Kindred, although such projects are difficult to pull off in the modern nights.\n\nAmong the hoary, rotting elite of the Camarilla, de Laurent and Beckett enjoy a certain status but an average Anarch has never heard of either of them. Still, the study of the origins of the Kindred persists and there are younger Noddists, some self-taught, who have found fragments of the Book of Nod among the possessions of an elder called away by the Beckoning or through trawling mortal archives who’s custodians didn’t realize what they had.\n\nIn the prompts and ideas that follow, the Noddists encountered are usually of this latter type.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vdfqNXU1pYhu6fGUtzSV77f", "key": "Chapter 1: Stories from the Land of Nod", "name": "Chapter 1: Stories from the Land of Nod", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#veUtpjF3qUhhRkRXxEFHRIX": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vXXJV12zWBynC1FzNskLxKL"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#veUtpjF3qUhhRkRXxEFHRIX", "key": "Level 1", "name": "Level 1", "parent": "#vZZ5K9156z6AGdtQum7cZ59", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vfIW1NEbYHTjTkTbfLlQWLa": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "The concoction is applied to the body or body part of the destroyed vampire. Since the decay of the remains — especially supernatural features such as fangs — only takes a few minutes at most, a swift performance is essential.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vfIW1NEbYHTjTkTbfLlQWLa", "key": "Process", "name": "Process", "parent": "#viscyWuAhJJkgwEXbt9URVv", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vg7bpLGQEjwHq9Ty6bHuNgj": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "The Kindred whispers a message to the mercury, which carries it through the blood collected in a ceremonially prepared bowl.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vg7bpLGQEjwHq9Ty6bHuNgj", "key": "Process", "name": "Process", "parent": "#vXXJV12zWBynC1FzNskLxKL", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vg95RNGbQU9LKfvccTQNJY4": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vpURI80xNIFm83d1x79uwKG", "#vQFxNTHo2vEHh2q1q8amYK7"], "choices": [], "desc": "Learned mostly by the most ostentatious of Tremere, this power is used to manipulate blood or vitae into finely crafted images—whether entertaining your fellows at Elysium with gaudy magician’s tricks or diverting flowing rivulets into painstakingly precise Hermetic sigils. A few others have mastered this power to help clean up others mistakes.\n\nIf used for more utilitarian purposes, add your dots in Blood Sorcery to any roll intended to locate, clean up or otherwise collect blood. Such a use also makes it very difficult for others to find traces of blood.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vg95RNGbQU9LKfvccTQNJY4", "key": "Shape the Sanguine Sacrament", "name": "Shape the Sanguine Sacrament", "parent": "#v7YWG63wCedVlJCqG9ecUpP", "props": [{"name": "Discipline", "type": "STRING", "value": "Blood Sorcery", "vk": "scalar"}, {"name": "Level", "type": "INTEGER", "value": 1, "vk": "scalar"}, {"name": "System", "type": "STRING", "value": "By making a successful Manipulation + Blood Sorcery roll, the user may craft the blood into any chape or image they desire. Complexity of the image varies by difficulty— a simple message of “Help!” or a basic polygonal shape may only be at Difficulty 2, while a lengthy diatribe or an intricate sculpture may be Difficulty 4 or higher. Failure on this roll means the blood fails to form the desired shape or does not respond at all—a Critical Success not only forms the desired image, but negates the need for any further rolls to change its shape for the duration of the scene.", "vk": "scalar"}, {"name": "Duration", "type": "STRING", "value": "One scene or until lapsed by user", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Discipline Power", "typeHash": "#vtm5DisciplinePower1"}, "#vgavXm3UCi00e2LIJBWnhGz": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vrHKKFv4t7ocqYmRlkWGYtk", "#v3ImjZpqk9Ua4micjboUWXj", "#vUth8ILAjxzA2B34lEdXtfq"], "choices": [], "desc": "The most notorious part of the Book of Nod among Noddist scholars is the Chronicle of Secrets, and few Kindred bring it up in polite company. While it covers a wide variety of topics, in truth the Chronicle of Secrets is concerned with only one thing: Gehenna. The Final Nights. When all vampires are judged for their crimes before the throne of Caine. (At least if you believe in such things.)\n\nWe learn about the signs of Gehenna but the nature of the calamity and its cause remain mysterious. Anarchs that concern themselves with the Book of Nod find these passages the most troubling as they feed both the worst despotic impulses of Camarilla Princes and the cruel zealotry of Sabbat saboteurs. With the excuse of an upcoming apocalypse, the worst crimes and sadism suddenly become palatable and humanity a forgotten concern. The story ideas below revolve around prophecy and how Kindred might react when faced with seemingly inevitable destruction.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vgavXm3UCi00e2LIJBWnhGz", "key": "The Chronicle of Secrets", "name": "The Chronicle of Secrets", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vgwcamkAuaVNTLcLFCV5TJy": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "You own several fragments from the book or have memorized sections of Caine’s history. Noddists seek you out hoping to examine your copies or hear you recite the tales, and they’re willing to pay for it. This isn’t always a monetary trade; some offer favors, an exchange of information, or access to other resources your character finds valuable. Once per story, when you grant someone access to your collection, gain three temporary dots in Resources (or other appropriate Background as approved by your Storyteller) for the remainder of the story, or the ability to call in a future favor from the Noddist.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vgwcamkAuaVNTLcLFCV5TJy", "key": "Collector", "name": "Collector", "parent": "#vIOxJ8gUbNioVFL94kTKkME", "props": [{"name": "Rating", "type": "INTEGER", "value": 4, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vibhHqq9DeEvdzcLIZKNNz0": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#v7YWG63wCedVlJCqG9ecUpP", "#vECoTfGtZxl1G8dGbjh70mG"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vibhHqq9DeEvdzcLIZKNNz0", "key": "Blood Sorcery", "name": "Blood Sorcery", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#viscyWuAhJJkgwEXbt9URVv": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vXF1U7y60joQiPQuuCVtKaS", "#vwNaLSj80pus8q1CxSG2Wji", "#vfIW1NEbYHTjTkTbfLlQWLa"], "choices": [], "desc": "This Ceremony allows for the preservation of pieces of a Kindred’s body even after they’ve been destroyed. The Ceremony has become more dangerous in the era of the Second Inquisition, as tangible proof of the Kindred’s existence poses more danger than ever before. Many of the Hecata and Ministry hunt down such relics, lest the secret of this ancient Ceremony draw unwanted attention from Kindred of the Camarilla or the Second Inquisition. Still, some morbid Kindred find relief in surrounding themselves with the remains of their ancestors (or descendants) and practitioners of Oblivion occasionally find other uses for such relics. To the mercurians of the thin-bloods, such relics are a source of speculation and an ingredient of unknown power for their alchemy.\n\nOnce created, the relic (usually in the form of a mummified hand, skull, femur, or desiccated eye) persists until destroyed or exposed to sunlight. At the Storyteller’s discretion, a particularly high roll or a critical success may grant the relic the power to persist despite sunlight.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#viscyWuAhJJkgwEXbt9URVv", "key": "Ashen Relic", "name": "Ashen Relic", "parent": "#vzNHzSv0fWOtZNQ0uwf4tHs", "props": [{"name": "Discipline", "type": "STRING", "value": "Oblivion", "vk": "scalar"}, {"name": "Level", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "System", "type": "STRING", "value": "The player makes their Ceremony test. A win preserves one small body part, such as a finger bone or a fang, while three successes in the margin can preserve a femur or skull.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Ceremony", "typeHash": "#vtm5Ceremony00000001"}, "#vitDdkZYIFZc2irxtkOUShR": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#v1D5o6cfcTwstmoImkLPxFy", "#vdSSIxSLNyXOcdQxIJmsdLv", "#vRMDbtSlj6PIs8rLb5TR2ov", "#vyIQORMSXq62IJTvVxnaEw8"], "choices": [], "desc": "The existing fragments of the Book of Nod appear on many different mediums. Parchment, ancient diaries, vellum, and of course stone tablets. In this prompt, an ancient tablet purportedly bearing words and images from the Book of Nod appears in the domain.\n\nIn a chronicle, the tablet can be fought over by competing power cliques. Its age and supposed provenance adds legitimacy to the Book of Nod’s claim to be an ancient text passed down from ancient vampires. Owning a physical piece of vampire history and culture is an exceedingly rare thing. If the owner plays their cards right, the status derived from simply possessing such a thing may even trump its actual contents, words from the Chronicle of Caine. How many modern Kindred can say that they hold something with such a direct connection to the Kindred of myth?\n\nAny group of Kindred powerful enough to keep hold of such a substantial piece of Noddist lore could potentially leverage it for both material and political gain. While most vampires are preoccupied with hiding themselves from mortals or the nightly hunt for blood, the masters of the tablet can present themselves as part of the lofty elite in the vampire world.\n\nWhile the tablet itself wouldn’t confer the praxis of a domain, its owner can make grand claims about the wisdom of Caine, the ancient laws of the Kindred and their purported eventual destiny. They can conceal real information locked within the tablet while holding the object itself up as the symbol of their authority and power. The Church of Caine would be particularly drawn to the tablet as it would prove the Book of Nod is as an ancient text and not the invention of the Sabbat or some other foe of the Camarilla.\n\nThe following story ideas revolve around the tablet as a symbol of prestige. The actual occult or mystical secrets locked within are left up to the needs of the story. A young coterie such as that of the players’ characters could be attracted to the Kindred holding the tablet because they’re curious about the origins of their kind, or because they believe it’ll grant some sort of supernatural power. A more ambitious coterie might even seek to steal it and use it to make their own reputation.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vitDdkZYIFZc2irxtkOUShR", "key": "The Tablet", "name": "The Tablet", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vj9tAROWWpgzum6YwW0zyet": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "A drop of mercury and one rouse check’s worth of blood.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vj9tAROWWpgzum6YwW0zyet", "key": "Ingredients", "name": "Ingredients", "parent": "#vXXJV12zWBynC1FzNskLxKL", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vjXkfjim9fMWyBDzUwMptzb": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "All actions are in service to the Third Generation, the thirteen vampires that will someday rise and destroy the world. There is nothing you won’t do to fulfill that goal, and you have devoted your entire existence to it. The blood you have inherited from your clan founder is secondary to this higher purpose. Your clan Bane can be ignored once per story while you are a Servitor of Irad.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vjXkfjim9fMWyBDzUwMptzb", "key": "Do the Will of the Ancients", "name": "Do the Will of the Ancients", "parent": "#vtFAEQT7PdM516PZcMZFvnG", "props": [{"name": "Rating", "type": "INTEGER", "value": 4, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vjZPhiKy9BLcV3ccYrGwNPk": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "You can’t do the work of the Antediluvians if you get discovered by others. Luckily, you have a lot of experience shielding your true intentions from the gaze of outsiders. You gain an additional die on rolls involving lying to other Kindred.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vjZPhiKy9BLcV3ccYrGwNPk", "key": "Shield of Irad", "name": "Shield of Irad", "parent": "#vtFAEQT7PdM516PZcMZFvnG", "props": [{"name": "Rating", "type": "INTEGER", "value": 1, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vk5bECyXw7y9JIrJV0KuDFL": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Sometimes you must act decisively in the name of the Third Generation, and that conviction adds additional strength to your act. Once per story, you can add three dice to a roll that is integral to your cult’s plans.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vk5bECyXw7y9JIrJV0KuDFL", "key": "Sword of Irad", "name": "Sword of Irad", "parent": "#vtFAEQT7PdM516PZcMZFvnG", "props": [{"name": "Rating", "type": "INTEGER", "value": 2, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vkDXxgPBT2Ssuchhugys6Dl": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vcDUKD1QYqYA4eDNMxUJN2P", "#v9cYn1buu7iDJPicK7e9YxQ", "#v59kZXILX7Km38BIdeqOO9u", "#vxzBVWJtxonH2XCrSkiiTiF", "#vuelg3QT7WPWU55clHim8Rc"], "choices": [], "desc": "(Salubri or Tremere Only)\n\nWhile some Noddists regard Saulot as a veritable saint, others who study the history of the Salubri and Saulot see him as a dangerous player in the eternal struggle: possibly the most sinister of all antediluvians. Clans Salubri and Tremere, among others, have studied the travels and words of Saulot, and fear the mastermind that may lurk behind the façade of saintliness.\n\nSaulot is rumored to have sired the Salubri as a means of testing his knowledge and creating goodwill towards his fellow antediluvians, with no qualms about discarding them as he vanished, a victim of diablerie by Tremere. Rumors spread among those in the know that Tremere may have lost the battle of wills when committing diablerie on Saulot and Saulot’s diablerie may have been simply another move in the Jyhad.\n\nIf Saulot’s ultimate goal is mastery over his fellow Antediluvians and all Kindred, he would manipulate a small remnant of philosophers, healers, and warriors as well as a world-spanning authoritarian cabal of once blood-bound sorcerers. With the recent fractures in the Tremere clan’s pyramid structure, the Beckoning, and the Gehenna Crusade, Saulot’s ultimate plans seem increasingly inscrutable. This does not stop many from speculation, however.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vkDXxgPBT2Ssuchhugys6Dl", "key": "Machinations of Saulot", "name": "Machinations of Saulot", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": "Loresheet", "typeHash": "#vtm5Loresheet0000001"}, "#vlb7c7YDmUeclLLOdamWvvq": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vlb7c7YDmUeclLLOdamWvvq", "key": "Loresheets", "name": "Loresheets", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vo5IhNTk0zU7T5dUjLms5yR": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "An Anarch gang has caused an uproar in several cities, demanding that all ghouls be freed from the enslavement of the Blood Bond through an impractical system of cycling ghouls through a *consensus circle* of just about every Kindred in the city. While they have yet to resort to violence themselves, their activism has caused divisions within the local Camarilla and Anarch Movement. While such ideas do sometimes percolate among the Anarchs, this gang has taken the novel approach of referencing Noddist texts in their appeals. Where did a group of so-called “Anarchs” get their hands on these scrolls? Are they somehow connected with a larger plot to turn ghouls against their masters? How will the Church of Caine respond when its own teachings are used to strip powerful benefactors of their loyal retainers?", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vo5IhNTk0zU7T5dUjLms5yR", "key": "The Anarchs", "name": "The Anarchs", "parent": "#vxt9FOsscR0jzHVxeS7AtbP", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vooC179GUYmhk1NUoUeRMlq": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "And there came a time when. Malkav. seer of Caine. stopped receiving visions. His eyes went dark and could no longer foretell fortunes. Even his companion, gentle Saulot, could not comfort him. Doubt consumed him and he left Enoch, Left his brothers and sisters, Left his father’s city and left in search of Caine. For many a long night. he was alone. He would not feed because he needed to know why; He would lay restless during the day because he no longer saw angels; His doubt blinded him, his existence a cage. He asked the One Above to guide him. and like Caine before. He sacrificed what was dear to him – his vision. This is how Malkav, blind, came upon Caine. In the shadows of a sycamore, Malkav spoke to his Father, Because God no longer spoke to him. There, in the night, Malkav asked a simple question of Caine. A question he needed answered to better understand his curse, And His silence. Malkav asked Caine, “Why?” “Why did you cast your brother’s blood to sand?” “Why did you cast yourself to darkness?”\n\n“Why did you refuse forgiveness when it was offered?” “Why did you condemn us, and our children, and their children’s children, to betray one another until the Final Nights? “Why were you blind to the love of God and your brother?” And with each question Caine’s anger grew and swelled, Not because of Malkav’s disrespect, or his doubt in him, Progenitor of his Race, God and Father to them all, But because Caine himself did not know. In Malkav’s face, Caine saw Abel and could say nothing. He no longer remembered: The love that cursed him to darkness; The words of God before his banishment; His brother’s voice; Were all forgotten. He knew that this misery would last until the End of Days, And this angered him. Then Caine said to Malkav: “I do not know, Seer, and nor shall you, And like my brother feared me, your brothers shall fear you, Your visions, and your burning questions. I condemn you to silence, The silence of madness so that you, like I, will be forever alone in doubt.” This is how Malkav was destined to madness, crushed by doubt, And so he waits until Gehenna to ask Caine once more—“Why?”", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-apocrypha.ttrpg", "form": "DEF", "guidance": [], "id": "#vooC179GUYmhk1NUoUeRMlq", "key": "Vencel Rickard’s Fragment", "name": "Vencel Rickard’s Fragment", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vp3t3qiM4qRZxhMbqiOxO6Y": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "You’re steeped in the lore of Gehenna, and you’ve learned many permutations of warped faiths that your fellow Kindred wrap themselves in. Once per session, when you discuss a vam- pire’s faith with them or observe them practicing their faith, you can extrapolate the rough nature of the doctrines, Convictions, or code that the religion focuses on. The Storyteller does not need to give you the exact wording, but must convey the primary themes, limitations, and beliefs, even those that are not evident in what the vampire has said or done.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vp3t3qiM4qRZxhMbqiOxO6Y", "key": "Dogma", "name": "Dogma", "parent": "#vZdjJ9QO32JA1Ppu8rU8VUY", "props": [{"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vpURI80xNIFm83d1x79uwKG": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Free (or One Rouse Check if using own Blood)", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vpURI80xNIFm83d1x79uwKG", "key": "Cost", "name": "Cost", "parent": "#vg95RNGbQU9LKfvccTQNJY4", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vq6p8A8F9LKpUkivE0qzDvW": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Your sire or Mawla taught you certain passages from the book, and may even have physical fragments in their possession. Once per story, you may seek their input on a matter regarding Noddist lore, gaining a two-dice bonus to any Occult test related to the book.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vq6p8A8F9LKpUkivE0qzDvW", "key": "Well-versed", "name": "Well-versed", "parent": "#vIOxJ8gUbNioVFL94kTKkME", "props": [{"name": "Rating", "type": "INTEGER", "value": 2, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vrHKKFv4t7ocqYmRlkWGYtk": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "A seer believed to be of Malkavian Blood has entered the city under the protection of a powerful mentor. The reason for their visit is unknown, but their reputation precedes them like a bad omen. The seer is believed to understand the signs of Gehenna like no other as many of their pronouncements have supposedly come to pass. The seer quotes the Chronicle of Secrets as if tutored by the most learned Noddist scholars. Is this seer here to liven up their patron’s salons? Or has a sign of Gehenna appeared for them to interpret or analyze? At first this seer’s presence is a novelty, but soon becomes a pressing concern as powerful Cainites begin to seek their advice and participate in dangerous Noddist rituals. When a very popular Anarch Kindred is destroyed during a vision quest guided by this seer, other Anarchs demand answers.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vrHKKFv4t7ocqYmRlkWGYtk", "key": "The Seer", "name": "The Seer", "parent": "#vgavXm3UCi00e2LIJBWnhGz", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vrI72Z7noCpOxfFfpcPLkpR": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Investigating the rising tide of blood cults and Gehenna worshipers has put you in a prime position to sift a few precious grains of truth from the bloated clot of lies that sits at the heart of most of these misbegotten faiths. Whether you want to believe it or not, you can’t deny the evidence you’ve gathered — and why not exploit it for yourself, rather than leaving it in the blood-stained hands of frothing zealots? Once you have studied the practices or texts of any blood cult, you are able to learn any Rituals or other unusual supernatural capabilities they possess without need of a teacher, although you must pay any experience point costs as normal.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vrI72Z7noCpOxfFfpcPLkpR", "key": "Red Truths", "name": "Red Truths", "parent": "#vZdjJ9QO32JA1Ppu8rU8VUY", "props": [{"name": "Rating", "type": "INTEGER", "value": 5, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vrNMVQ3UXsWMPfVWKsvpWg8": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "I don’t care whether the Book of Nod is real or not. What matters to me is the way it’s being used. The Princes of the Camarilla cloak themselves in veneration of our ancient past when they wish to pass the worst of their edicts, pretending that their greed is merely observance of Caine’s law. The Book of Nod is a tool used to suppress us, no matter its veracity. As Anarchs, we have two options: We have to suppress it, or subvert it.\n\nKindred laws and traditions often extend back to the Book of Nod. Here are a few of them, compiled for easy reference. Their arrangement is in roughly chronological order: Many Anarchs and disaffected autarkis formerly of the Camarilla have sought out previous traditions, questioning the Ivory Tower’s pretence as the bastion of Kindred orthodoxy.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-kindred-laws-and-traditions.ttrpg", "form": "DEF", "guidance": [], "id": "#vrNMVQ3UXsWMPfVWKsvpWg8", "key": "Chapter 3: Kindred Laws and Traditions", "name": "Chapter 3: Kindred Laws and Traditions", "parent": null, "props": [{"name": "Epigraph", "type": "STRING", "value": "— Salvador Garcia, Anarch ideologue", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vst24rHGB1VFHUU0hrXmjij": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Oblivion’s Sight or Where the Veil Thins", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vst24rHGB1VFHUU0hrXmjij", "key": "Prerequisite Power", "name": "Prerequisite Power", "parent": "#vPZ5VdtH4OQ9RG8ISIh6aFE", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vtFAEQT7PdM516PZcMZFvnG": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vjZPhiKy9BLcV3ccYrGwNPk", "#vk5bECyXw7y9JIrJV0KuDFL", "#vv74tIJzBD5TsSiwsqDolit", "#vjXkfjim9fMWyBDzUwMptzb", "#v5Vae038Ro11NKDSWSRJmyh"], "choices": [], "desc": "According to the Book of Nod, Irad the Strong was the third childe of Caine, and he served as his sire’s enforcer and military leader in the First City. The Kindred of the Servitors of Irad seek to emulate that mythological vampire, who is said to have pledged to serve the Antediluvians in all things before his kin or his childer destroyed him. They hope that, if they spend their existence showing they serve the Antediluvians, they will be spared when the ancients rise. Irad believed it, but received the revelation too late to preserve himself.\n\nThe cult doesn’t actually have any contact with the Third Generation, but they assume that the Antediluvians would want the elders of Kindred society to be weak and divided. As such, they infiltrate any vampiric organization they can find — Camarilla cities, Anarch gatherings, and even other cults — to sow dissension and shatter fragile alliances. And now you’re one such deep cover member. You’re cut off from the other members of your cult, trying to enact a hazily understood plan set down by mythological figures with whom you have no direct contact, with the knowledge that if any other vampire ever found out, you’d be immediately and painfully killed. But you have faith, and that’s enough.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vtFAEQT7PdM516PZcMZFvnG", "key": "Servitor of Irad", "name": "Servitor of Irad", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": "Loresheet", "typeHash": "#vtm5Loresheet0000001"}, "#vu6mLIPIUCrxIVq1yh9FdVu": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "A tyrannical Camarilla Prince has proclaimed bizarre new “Traditions”or “Courtesies” in their domain restricting which clans are allowed to Embrace, which individuals may claim Domain, or even classes of acceptable Ghouls. They impose unequal, onerous responsibilities on local Kindred, and new draconian punishments for the slightest offenses. The tyrant’s edicts are backed by a reclusive group of scholars claiming to possess a complete and perfectly translated version of the Chronicle of Shadows. Many believe this is simply a power grab by a power-hungry tyrant, but others suspect that the Prince is backed by a shadowy figure, recently risen from torpor, who may even by a member of the Primogen council. Unsurprisingly the Kindred saddled with the new restrictions have become agitated and are already looking for a way to overturn these supposedly “rediscovered” Traditions of Caine. A cunning coterie could find great opportunity in their plight, or find favor among the powers that be by turning over those attempting to undermine the new order.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vu6mLIPIUCrxIVq1yh9FdVu", "key": "The Traditions", "name": "The Traditions", "parent": "#vxt9FOsscR0jzHVxeS7AtbP", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vuCni6P6OnrB94L5cyBSpl3": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "**I. The Masquerade** Thou shall not reveal thy true nature to those not of the Blood. Doing such shall renounce thy claims of Blood.\n\n**II. Domain** Thy domain is thine own concern. All others owe thee respect while in it. None may challenge thy word while in thy domain.\n\n**III. Progeny** Thou shall only Sire another with the permission of thine elder. If thou createst another without thine Elder’s leave, both thou and thy Progeny shall be slain.\n\n**IV. Accounting** Those thou create are thine own children. Until thy Progeny shall be Released, thou shall command them in all things. Their sins are thine to endure.\n\n**V. Hospitality** Honor one another’s domain. When thou comest to a foreign city, thou shall present thyself to the one who ruleth there. Without the word of acceptance, thou art nothing.\n\n**VI. Destruction** Thou art forbidden to destroy another of thy kind. The right of destruction belongeth only to thine Elder. Only the Eldest among thee shall call the Blood Hunt.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-kindred-laws-and-traditions.ttrpg", "form": "DEF", "guidance": [], "id": "#vuCni6P6OnrB94L5cyBSpl3", "key": "Traditions of the Camarilla", "name": "Traditions of the Camarilla", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vuelg3QT7WPWU55clHim8Rc": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "Your expertise in Saulot’s ways gives you an advantage few others have. You possess traits of both Clans Salubri and Tremere. You may learn Blood Sorcery or Fortitude as if they were a Clan Discipline if they weren’t already, but suffer both Clan Banes and Compulsions.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vuelg3QT7WPWU55clHim8Rc", "key": "Ultimate Disguise", "name": "Ultimate Disguise", "parent": "#vkDXxgPBT2Ssuchhugys6Dl", "props": [{"name": "Rating", "type": "INTEGER", "value": 5, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vv74tIJzBD5TsSiwsqDolit": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "You are firmly convinced you know the will of the Antediluvians. Perhaps you even hear their voices in your head, or gain prophetic dreams from them. As long as you are a member of the cult, you can take an additional Conviction that is directly related to the goals of your infiltration (your membership in the cult acts as your “touchstone” for the purposes of this Conviction). If you infiltrate a new group, you can change your Conviction to reflect the new assignment.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vv74tIJzBD5TsSiwsqDolit", "key": "Know the Will of the Ancients", "name": "Know the Will of the Ancients", "parent": "#vtFAEQT7PdM516PZcMZFvnG", "props": [{"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vwNaLSj80pus8q1CxSG2Wji": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "The decaying body of a vampire, plus salt and herbs associated with embalming.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vwNaLSj80pus8q1CxSG2Wji", "key": "Ingredients", "name": "Ingredients", "parent": "#viscyWuAhJJkgwEXbt9URVv", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vxPYMAPb4zfgvsqMAq0F1HL": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "The time has come, My Children, For me to bid the night goodbye. But know that I do not leave you. Await the time when I join you again After you have learned the wages Of your vanity, sin and pride. And mark well the heralds of my return For I do not leave the affairs of my house To be tended by the Children of Seth.”\n\n“And I traveled for a hundred years before I found My father’s first wife Whose blood I drank And yet she was Awake still. “I must talk to the One Above,” I said And she smiled. “Talk to Him,” she said, “But know that he has turned his back on you For your sin.” At this I cried thirteen tears of blood And named them as each fell When Lilith said: “Why do you call our children’s names? They cannot And will not Help you. They are nothing but other sins Committed to make sweet Abel’s death Less sharp in your cold heart.” And to her I said, “Mother, lover, I cannot feel. We made them to buoy me And yet they drag me into [Hell].”\n\nAnd I grew tired, My dead heart heavy with all that I had done. So I pledged to sleep until my wrongs Had righted themselves. With Lilith’s knife, I cut myself and sang: “From these open wounds Life shall come from death, As the last daughter Bearing the mark of the moon, Sends [Lasombra’s] bane to the ashes, Sends [Gangrel’s] brood to the cold stone, Infests [Nosferatu’s] den with [snakes] and strikes down his wife, And pierces the rest of my grandchilder With the fires of the wise.” At these words, I sank Embraced by the cold arms of Lilith’s garden. Please [God], Erase my folly And end this.\n\nOn the last night, the eve of Gehenna, All of Caine’s race shall know of God’s judgment", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-apocrypha.ttrpg", "form": "DEF", "guidance": [], "id": "#vxPYMAPb4zfgvsqMAq0F1HL", "key": "Shroud of Kaymakli", "name": "Shroud of Kaymakli", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vxSToEhGvCkb9l6m34RMw5W": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "There’s a new face among local Noddist circles, someone maintaining a mortal persona as the reclusive proprietor of an antique book store. They only make a rare appearance but seem to have access to fragments from the Book of Nod nobody else has seen. Their disheveled appearance and monomaniacal focus suggests the stories from the land of Nod have taken hold of their imagination to a singular degree. It takes a while for anyone to grasp the truth: The newcomer is not a vampire at all but a mortal who has managed to unearth some of the same secrets the Kindred have hunted for a millennia. The question becomes: Should they be eliminated? Made into a ghoul? Embraced?", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vxSToEhGvCkb9l6m34RMw5W", "key": "The Misunderstanding", "name": "The Misunderstanding", "parent": "#vEi8rlfjLZcyj5inOebULCG", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vxt9FOsscR0jzHVxeS7AtbP": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#vu6mLIPIUCrxIVq1yh9FdVu", "#vo5IhNTk0zU7T5dUjLms5yR", "#vCMSpHcrtnlbF5maXfpl3bU", "#vMzlmnq7vUjRMaYlS2T9KrS"], "choices": [], "desc": "The second collection of texts in the Book of Nod, The Chronicle of Shadows, explores Caine’s commandments to his progeny and the wisdom of the clan founders. Although rarely acknowledged, the Camarilla’s Traditions are often assumed to be interpretations of Caine’s Law. While the Book of Nod’s lore is most often pursued by elders, Camarilla members, Bahari, and the Church of Caine, some Anarchs have also become interested in the pronouncements of Caine and the Brujah founder on how Kindred should treat mortals and ghoul servants.\n\nMore esoterically minded Kindred might pursue the chronicle for the secrets of the restless dead. Though exceedingly rare, a few scholarly minded hunters could also find a use for these collected writings. How vampire “culture” views mortals and how they’ve historically used mortal society could give a shrewd group of hunters new insights into how to approach the vampire problem. The ideas below deal with the underpinnings of Kindred society, law, and politics.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vxt9FOsscR0jzHVxeS7AtbP", "key": "The Chronicle of Shadows", "name": "The Chronicle of Shadows", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vxzBVWJtxonH2XCrSkiiTiF": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "When Saulot was destroyed, his childer supposedly went mad, slaying one another as they were drawn to the site of Saulot’s awakening. Once per story, you can summon your sire or one of your childer or someone who has tasted your Blood as per the Presence power Summon, using your Auspex or Dominate rating instead of PresenceYou can also ignore such a summons yourself, once per story.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-loresheets.ttrpg", "form": "DEF", "guidance": [], "id": "#vxzBVWJtxonH2XCrSkiiTiF", "key": "The Madness of Blood", "name": "The Madness of Blood", "parent": "#vkDXxgPBT2Ssuchhugys6Dl", "props": [{"name": "Rating", "type": "INTEGER", "value": 4, "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loresheet Level", "typeHash": "#vtm5LoresheetLevel01"}, "#vyIQORMSXq62IJTvVxnaEw8": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "A mortal researcher has unearthed an ancient stone tablet with writing that local Noddist Kindred recognize as being in ancient Enochian. Unfortunately, the mortal is something of a celebrity, a high-profile academic with regular appearances on television commenting on the issues of the day. This means that it’s difficult to steal the tablet discreetly to say nothing of dealing with the researcher more permanently. What’s worse, they might manage to decipher the text. Of course, the contents would probably be understood as myth, not fact, but the thought of the stories of Enoch becoming public knowledge is still uncomfortable for Kindred concerned with the Masquerade.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-stories-from-the-land-of-nod.ttrpg", "form": "DEF", "guidance": [], "id": "#vyIQORMSXq62IJTvVxnaEw8", "key": "The Mortal", "name": "The Mortal", "parent": "#vitDdkZYIFZc2irxtkOUShR", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vzNHzSv0fWOtZNQ0uwf4tHs": {"aliases": null, "book": "book-of-nod-apocrypha", "children": ["#viscyWuAhJJkgwEXbt9URVv"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-disciplines.ttrpg", "form": "DEF", "guidance": [], "id": "#vzNHzSv0fWOtZNQ0uwf4tHs", "key": "Level 2", "name": "Level 2", "parent": "#vaWaBS8y33ubwzb0KOpvMOc", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#vzbwSVjAYn0bRWkiC5Muj5C": {"aliases": null, "book": "book-of-nod-apocrypha", "children": [], "choices": [], "desc": "**The Law of Leadership** Honor the Eldest among you, for he is to rule my House when I am absent.\n\n**The Law of Protection** Ward the mortals from Caine’s descendants and treat them with honor in all things.\n\n**The Law of Destruction** Slay not those of the Blood, for that judgment is for the Eldest alone.\n\n**The Law of the Word** Deceive not those of the Blood, for my House is founded on Truth.\n\n**The Law of Judgment** Judge those of Caine’s blood and punish them should they be found wanting.", "entries": [], "enum": null, "file": "vtm5e-0.5-book-of-nod-apocrypha-kindred-laws-and-traditions.ttrpg", "form": "DEF", "guidance": [], "id": "#vzbwSVjAYn0bRWkiC5Muj5C", "key": "The Laws of Haqim", "name": "The Laws of Haqim", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}}, "src": "data/book-of-nod-apocrypha.js"};var T=window.VTM5E=window.VTM5E||{books:{},entities:{},loaded:{}};
T.loaded[d.src]=true;T.books[d.book.id]=d.book;
for(var h in d.entities){T.entities[h]=d.entities[h];}})();
